func (p *parser) parseUnary() (node, *Error) {
    if t := p.peek(); t is op - / + / ! {
        p.next()
        operand, err := p.parseUnary()
        return &unaryNode{pos: t.pos, op: t.text, operand: operand}
    }
    return p.parsePower()
}

func (p *parser) parsePower() (node, *Error) {
    base, err := p.parsePrimary()
    if err != nil { return nil, err }
    if p.matchOp("^") {
        exp, err := p.parseUnary()
        return &binaryNode{pos: opPos, op: "^", left: base, right: exp}
    }
    return base
}
```

