{"path":"expr/lexer.go","content":"package expr

import (
	"fmt"
	"strconv"
	"strings"
)

type tokenKind int

const (
	tokEOF tokenKind = iota
	tokNum
	tokIdent
	tokOp
)

type token struct {
	kind tokenKind
	text string
	pos  int
	num  float64
}

func isDigit(c byte) bool { return c >= '0' && c <= '9' }

func isIdentStart(c byte) bool {
	return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || c == '_'
}

func isIdentPart(c byte) bool { return isIdentStart(c) || isDigit(c) }

// twoCharOps are the two-character operators; checked before single characters.
const twoCharOps = "<=>===!=&&||"

const oneCharOps = "+-*/%^(),?:<>!"

// tokenize converts src into a token list terminated by an EOF token.
// It returns *Error for invalid characters or malformed numbers.
func tokenize(src string) ([]token, *Error) {
	var toks []token
	i := 0
	for i < len(src) {
		c := src[i]
		switch {
		case c == ' ' || c == '\t' || c == '\n':
			i++
		case isDigit(c) || c == '.':
			start := i
			if isDigit(c) {
				for i < len(src) && isDigit(src[i]) {
					i++
				}
			} else {
				i++ // leading '.'
			}
			if i < len(src) && src[i] == '.' {
				i++
				for i < len(src) && isDigit(src[i]) {
					i++
				}
			}
			// Exponent part: e/E followed by optional sign and at least one digit.
			if i < len(src) && (src[i] == 'e' || src[i] == 'E') {
				j := i + 1
				if j < len(src) && (src[j] == '+' || src[j] == '-') {
					j++
				}
				if j < len(src) && isDigit(src[j]) {
					for j < len(src) && isDigit(src[j]) {
						j++
					}
					i = j
				}
			}
			text := src[start:i]
			val, err := strconv.ParseFloat(text, 64)
			if err != nil {
				return nil, &Error{Pos: start, Msg: fmt.Sprintf("invalid number %q", text)}
			}
			toks = append(toks, token{kind: tokNum, text: text, pos: start, num: val})
		case isIdentStart(c):
			start := i
			for i < len(src) && isIdentPart(src[i]) {
				i++
			}
			toks = append(toks, token{kind: tokIdent, text: src[start:i], pos: start})
		default:
			if i+1 < len(src) && strings.ContainsRune(twoCharOps, rune(src[i+1])) &&
				strings.ContainsRune(twoCharOps, rune(c)) &&
				isTwoCharOp(src[i:i+2]) {
				toks = append(toks, token{kind: tokOp, text: src[i : i+2], pos: i})
				i += 2
				continue
			}
			if strings.ContainsRune(oneCharOps, rune(c)) {
				toks = append(toks, token{kind: tokOp, text: string(c), pos: i})
				i++
				continue
			}
			return nil, &Error{Pos: i, Msg: fmt.Sprintf("unexpected character '%c'", c)}
		}
	}
	toks = append(toks, token{kind: tokEOF, pos: len(src)})
	return toks, nil
}

func isTwoCharOp(s string) bool {
	switch s {
	case "<=", ">=", "==", "!=", "&&", "||":
		return true
	}
	return false
}
