{"content":"package expr

import "fmt"

// parser is a recursive descent parser over a token list.
type parser struct {
	toks   []token
	i      int
	srcLen int // position of the EOF token
}

func (p *parser) peek() token  { return p.toks[p.i] }
func (p *parser) next() token  { t := p.toks[p.i]; p.i++; return t }
func (p *parser) atEOF() bool  { return p.peek().kind == tokEOF }

// matchOp consumes and reports a matching operator token.
func (p *parser) matchOp(s string) bool {
	t := p.peek()
	if t.kind == tokOp && t.text == s {
		p.i++
		return true
	}
	return false
}

// unexpected reports the token found where none was allowed.
func (p *parser) unexpected(t token) *Error {
	if t.kind == tokEOF {
		return &Error{Pos: p.srcLen, Msg: "unexpected end of input"}
	}
	return &Error{Pos: t.pos, Msg: fmt.Sprintf("unexpected token %q", t.text)}
}

// expectOp consumes a required operator, reporting "expected ..." otherwise.
func (p *parser) expectOp(s string) *Error {
	if p.matchOp(s) {
		return nil
	}
	t := p.peek()
	pos := t.pos
	if t.kind == tokEOF {
		pos = p.srcLen
	}
	return &Error{Pos: pos, Msg: fmt.Sprintf("expected %q", s)}
}

// parseExpr parses a complete expression at the lowest precedence level.
func (p *parser) parseExpr() (node, *Error) { return p.parseTernary() }

func (p *parser) parseTernary() (node, *Error) {
	cond, err := p.parseOr()
	if err != nil {
		return nil, err
	}
	if !p.matchOp("?") {
		return cond, nil
	}
	qPos := p.toks[p.i-1].pos
	then, err := p.parseExpr()
	if err != nil {
		return nil, err
	}
	if err := p.expectOp(":"); err != nil {
		return nil, err
	}
	els, err := p.parseExpr()
	if err != nil {
		return nil, err
	}
	return &ternaryNode{pos: qPos, cond: cond, then: then, els: els}, nil
}

func (p *parser) parseOr() (node, *Error) {
	left, err := p.parseAnd()
	if err != nil {
		return nil, err
	}
	for p.peek().kind == tokOp && p.peek().text == "||" {
		op := p.next()
		right, err := p.parseAnd()
		if err != nil {
			return nil, err
		}
		left = &binaryNode{pos: op.pos, op: "||", left: left, right: right}
	}
	return left, nil
}

func (p *parser) parseAnd() (node, *Error) {
	left, err := p.parseEquality()
	if err != nil {
		return nil, err
	}
	for p.peek().kind == tokOp && p.peek().text == "&&" {
		op := p.next()
		right, err := p.parseEquality()
		if err != nil {
			return nil, err
		}
		left = &binaryNode{pos: op.pos, op: "&&", left: left, right: right}
	}
	return left, nil
}

func (p *parser) parseEquality() (node, *Error) {
	left, err := p.parseComparison()
	if err != nil {
		return nil, err
	}
	for p.peek().kind == tokOp && (p.peek().text == "==" || p.peek().text == "!=") {
		op := p.next()
		right, err := p.parseComparison()
		if err != nil {
			return nil, err
		}
		left = &binaryNode{pos: op.pos, op: op.text, left: left, right: right}
	}
	return left, nil
}

func (p *parser) parseComparison() (node, *Error) {
	left, err := p.parseAdditive()
	if err != nil {
		return nil, err
	}
	for p.peek().kind == tokOp {
		t := p.peek()
		if t.text == "<" || t.text == "<=" || t.text == ">" || t.text == ">=" {
			op := p.next()
			right, err := p.parseAdditive()
			if err != nil {
				return nil, err
			}
			left = &binaryNode{pos: op.pos, op: op.text, left: left, right: right}
			continue
		}
		break
	}
	return left, nil
}

func (p *parser) parseAdditive() (node, *Error) {
	left, err := p.parseMultiplicative()
	if err != nil {
		return nil, err
	}
	for p.peek().kind == tokOp && (p.peek().text == "+" || p.peek().text == "-") {
		op := p.next()
		right, err := p.parseMultiplicative()
		if err != nil {
			return nil, err
		}
		left = &binaryNode{pos: op.pos, op: op.text, left: left, right: right}
	}
	return left, nil
}

func (p *parser) parseMultiplicative() (node, *Error) {
	left, err := p.parseUnary()
	if err != nil {
		return nil, err
	}
	for p.peek().kind == tokOp {
		t := p.peek()
		if t.text == "*" || t.text == "/" || t.text == "%" {
			op := p.next()
			right, err := p.parseUnary()
			if err != nil {
				return nil, err
			}
			left = &binaryNode{pos: op.pos, op: op.text, left: left, right: right}
			continue
		}
		break
	}
	return left, nil
}

// parseUnary handles prefix -, + and !.
func (p *parser) parseUnary() (node, *Error) {
	if t := p.peek(); t.kind == tokOp && (t.text == "-" || t.text == "+" || t.text == "!") {
		op := p.next()
		operand, err := p.parseUnary()
		if err != nil {
			return nil, err
		}
		return &unaryNode{pos: op.pos, op: op.text, operand: operand}, nil
	}
	return p.parsePower()
}

// parsePower handles right-associative ^, whose right operand may be a unary.
func (p *parser) parsePower() (node, *Error) {
	base, err := p.parsePrimary()
	if err != nil {
		return nil, err
	}
	if p.peek().kind == tokOp && p.peek().text == "^" {
		op := p.next()
		exp, err := p.parseUnary()
		if err != nil {
			return nil, err
		}
		return &binaryNode{pos: op.pos, op: "^", left: base, right: exp}, nil
	}
	return base, nil
}

func (p *parser) parsePrimary() (node, *Error) {
	t := p.peek()
	switch t.kind {
	case tokNum:
		p.next()
		return &numNode{pos: t.pos, val: t.num}, nil
	case tokIdent:
		if t.text == "true" || t.text == "false" {
			p.next()
			val := float64(0)
			if t.text == "true" {
				val = 1
			}
			return &numNode{pos: t.pos, val: val}, nil
		}
		p.next()
		if p.peek().kind == tokOp && p.peek().text == "(" {
			return p.parseCall(t)
		}
		return &varNode{pos: t.pos, name: t.text}, nil
	case tokOp:
		if t.text == "(" {
			p.next()
			inner, err := p.parseExpr()
			if err != nil {
				return nil, err
			}
			if err := p.expectOp(")"); err != nil {
				return nil, err
			}
			return inner, nil
		}
		return nil, p.unexpected(t)
	default: // EOF
		return nil, p.unexpected(t)
	}
}

// parseCall parses a built-in function call body; t is the name token already consumed.
func (p *parser) parseCall(t token) (node, *Error) {
	p.next() // consume '('
	var args []node
	if !(p.peek().kind == tokOp && p.peek().text == ")") {
		for {
			a, err := p.parseExpr()
			if err != nil {
				return nil, err
			}
			args = append(args, a)
			if !p.matchOp(",") {
				break
			}
		}
	}
	if err := p.expectOp(")"); err != nil {
		return nil, err
	}
	fn, ok := builtins[t.text]
	if !ok {
		return nil, &Error{Pos: t.pos, Msg: fmt.Sprintf("unknown function %q", t.text)}
	}
	return &callNode{pos: t.pos, name: t.text, args: args, fn: fn}, nil
}
