{"content":"package expr

import "fmt"

// node is an internal AST node produced by the parser.
type node interface {
	evaluate(vars map[string]float64) (float64, *Error)
	pos() int
}

type numNode struct {
	pos int
	val float64
}

func (n *numNode) evaluate(map[string]float64) (float64, *Error) { return n.val, nil }
func (n *numNode) pos() int                                       { return n.pos }

type varNode struct {
	pos  int
	name string
}

func (n *varNode) evaluate(vars map[string]float64) (float64, *Error) {
	v, ok := vars[n.name]
	if !ok {
		return 0, &Error{Pos: n.pos, Msg: fmt.Sprintf("unknown variable %q", n.name)}
	}
	return v, nil
}

func (n *varNode) pos() int { return n.pos }

type unaryNode struct {
	pos     int
	op      string
	operand node
}

func (n *unaryNode) pos() int { return n.pos }

type binaryNode struct {
	pos   int
	op    string
	left  node
	right node
}

func (n *binaryNode) pos() int { return n.pos }

type ternaryNode struct {
	pos  int
	cond node
	then node
	els  node
}

func (n *ternaryNode) pos() int { return n.pos }

type callNode struct {
	pos  int
	name string
	fn   *builtin
	args []node
}

func (n *callNode) pos() int { return n.pos }
